def S1s(self, sort_key='area', reverse=True, return_type='both'):
    """List of S1 (scintillation) signals

    Returns an :class:`pax.datastructure.Peak` class.
    """
    if return_type == 'tpc':
        return self._get_peaks_by_type('s1', sort_key, reverse)
    elif return_type == 'veto':
        return self._get_peaks_by_type('veto', sort_key, reverse)
    else:
        # Assuming 'both' means returning both types
        s1_peaks = self._get_peaks_by_type('s1', sort_key, reverse)
        veto_peaks = self._get_peaks_by_type('veto', sort_key, reverse)
        return s1_peaks + veto_peaks
